bash -lc python - <<'PY'
import os,json,glob
for p in glob.glob('/mnt/data/*'):
 try:
  s=os.path.getsize(p)
  if p.endswith('.json'):
   x=json.load(open(p))
   if 'mapping' in x:
    nodes=x['mapping']; cnt=sum(1 for a in nodes.values() if a.get('message',{} ) and (a.get('message') or {}).get('author',{}).get('role')=='user'); typ='convo nodes='+str(len(nodes))+' user='+str(cnt)
   elif 'messages' in x:
    typ='NLM messages='+str(len(x['messages']))
   else: typ=str(list(x.keys())[:8])
  else:typ='PDF'
  print(os.path.basename(p)[:85],f'{s/1e6:.1f}MB',typ)
 except Exception as e: print(type(e).__name__,str(e)[:100])
