bash -lc python - <<'PY'
from bs4 import BeautifulSoup
from pathlib import Path
p=Path('/mnt/data/SAT _ H(s)H — The Glass Sausage Factory.html')
s=BeautifulSoup(p.read_text(encoding='utf-8'), 'html.parser')
print('title',s.title.text if s.title else None)
for el in s.select('a[href*="whirligig"],section.whirligig-feature, .whirligig-emblem'):
 print('TAG:', el.name, 'CLASS:',el.get('class'), 'HREF:',el.get('href'), 'TEXT:',el.get_text(' ',strip=True)[:350]);
print('Total links',len(s.find_all('a')))
for i,sect in enumerate(s.find_all(['section','article'])):
 h=sect.find(['h2','h3']);
 if h and any(x in h.get_text(' ',strip=True).lower() for x in ['visual','geometry','atlas','gallery','laborat']): print('Section',i,sect.get('id'),h.get_text(' ',strip=True)[:180])
