<body><main><small>THE GLASS SAUSAGE FACTORY / GEOMETRY LABORATORY / SANDBOXED</small><h1>Whirligig · R/Q</h1><p>Two equations ride on opposite hemispheres of a sphere whose diameter matches the torus tube. A constrained moving center, sphere orientation, orthogonal gimbal hinges and R–Q crossbar determine a rotating pen; forward intersections with the torus generate the composite <i>Curvy Lisa</i> trace.</p>
<div class="bar"><button id="play">Pause</button><button id="reset">Restart</button><button id="svg">Export Curvy Lisa SVG</button><select id="preset" aria-label="Equation pair"><option value="base">R/Q harmonics (archive example)</option><option value="first">First pair harmonics</option><option value="flat">Flat R, oscillating Q</option></select><button id="trail">Hide guide lines</button></div>
<div class="row"><div class="plate"><span>TORUS + EQUAL-DIAMETER SPHERE · DRAG TO ORBIT</span><canvas id="mechanism" aria-label="3D projected coupled Whirligig apparatus"></canvas></div><div class="plate"><span>CURVY LISA · TORUS WALL COMPOSITE</span><canvas id="output" aria-label="Live mechanically coupled output"></canvas></div></div>
<div class="controls">
<label>Equation R amplitude <output id="vr"></output><input data-key="ra" type="range" min="0" max="1" step=".01" value=".55"></label>
<label>Equation Q amplitude <output id="vq"></output><input data-key="qa" type="range" min="0" max="1" step=".01" value=".60"></label>
<label>Q phase <output id="vp"></output><input data-key="ph" type="range" min="-3.14" max="3.14" step=".02" value="0"></label>
<label>R gimbal turns <output id="vg1"></output><input data-key="g1" type="range" min="-2" max="2" step="1" value="0"></label>
<label>Q gimbal turns <output id="vg2"></output><input data-key="g2" type="range" min="-2" max="2" step="1" value="1"></label>
<label>Pen turns <output id="vpt"></output><input data-key="pt" type="range" min="0" max="8" step="1" value="4"></label>
<label>Major radius R <output id="vmajor"></output><input data-key="major" type="range" min="1.25" max="2.4" step=".05" value="1.6"></label>
<label>Tube & sphere radius a=b <output id="va"></output><input data-key="minor" type="range" min=".3" max=".8" step=".05" value=".55"></label>
<label>Time fraction <output id="vt"></output><input id="time" type="range" min="0" max="1" step=".002" value="0"></label>
</div><div id="stats" class="stats" role="status">Computing geometry…</div>
<p class="foot">This is a browser reconstruction of the historical <b>b=a</b> limiting setup. Its selected contact obeys the analytic no-slip condition at one nominated point; because equal radii create a nonisolated contact set, this does <b>not</b> certify no-slip across every point of contact. A small, explicit pen aiming bias and locally constructed normal-plane frame are visualization choices. No isomorphism or physical law is assumed. Research reference: <a href="https://github.com/Satobloc/HsH/tree/main/tools/whirligig_rq">Whirligig R/Q Python solver</a>.</p></main>
<script>(()=>{'use strict';const $=s=>document.querySelector(s),PI=Math.PI,TWO=2*PI,N=241,mc=$('#mechanism'),oc=$('#output'),m=mc.getContext('2d'),o=oc.getContext('2d'),inputs=[...document.querySelectorAll('[data-key]')];let run=true,show=true,phase=0,az=.7,el=.45,drag=false,px=0,py=0,last=performance.now(),data=[],cfg=null;
const add=(a,b)=>a.map((x,i)=>x+b[i]),sub=(a,b)=>a.map((x,i)=>x-b[i]),mul=(a,k)=>a.map(x=>x*k),dot=(a,b)=>a.reduce((v,x,i)=>v+x*b[i],0),cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]],norm=a=>Math.hypot(...a),unit=a=>mul(a,1/Math.max(1e-12,norm(a)));function Rx(v,t){let c=Math.cos(t),s=Math.sin(t);return[v[0],c*v[1]-s*v[2],s*v[1]+c*v[2]]}function Ry(v,t){let c=Math.cos(t),s=Math.sin(t);return[c*v[0]+s*v[2],v[1],-s*v[0]+c*v[2]]}
function params(){return Object.fromEntries(inputs.map(x=>[x.dataset.key,+x.value]))}
function equation(t,c,which){let p=$('#preset').value;if(which==='r')return p==='flat'?0:c.ra*(p==='first'?Math.cos(t):Math.cos(2*t))+.15*Math.sin(3*t);return c.qa*Math.sin(p==='first'?2*t:3*t+c.ph)+.1*Math.cos(5*t)}
function sample(t,c){const R=c.major,a=c.minor,b=a,rho=R,gear=(R+a)/b,g=gear*t;const er=[Math.cos(t),Math.sin(t),0],et=[-Math.sin(t),Math.cos(t),0],ez=[0,0,1],center=mul(er,rho); // body-to-world orientation Q = W B^T
 const rr=[Math.sin(g),0,Math.cos(g)],tt=[Math.cos(g),0,-Math.sin(g)],nn=[0,1,0];function Q(v){return add(add(mul(er,dot(v,rr)),mul(et,dot(v,tt))),mul(ez,dot(v,nn)))}
 function polar(y,south){const co=.83+.38*Math.tanh(y),th=south?PI-co:co;return [Math.sin(th)*Math.cos(t),Math.sin(th)*Math.sin(t),Math.cos(th)]}
 const r=polar(equation(t,c,'r'),false),q=polar(equation(t,c,'q'),true);const pr=add(center,mul(Q(Ry(r,c.g1*t)),b)),pq=add(center,mul(Q(Rx(q,c.g2*t)),b));
 const connector=sub(pq,pr),dir=unit(connector),mid=mul(add(pr,pq),.5);let ref=[0,0,1];if(Math.abs(dot(ref,dir))>.92)ref=[0,1,0];const u=unit(sub(ref,mul(dir,dot(ref,dir)))),v=unit(cross(dir,u));const angle=c.pt*t;let pen=unit(add(mul(u,Math.cos(angle)),mul(v,Math.sin(angle)))); // bias aims toward tube wall from centerline
 pen=unit(add(mul(pen,.62),mul(er,.38)));const contact=mul(er,R+a);return{center,pr,pq,mid,dir,pen,contact,r,q,er,Q}}
