// These are two independent, closed BODY sphere curves on east and west sides.
// Each scalar equation determines polar aperture; a monotone azimuth adapter
// supplies the second coordinate. This is an explicit representation choice.
function bearing(t,c,side){
 const k=side==='r'?0:.7;
 return t+.11*(Math.sin(2*t+k)-Math.sin(k))
        +.03*(Math.tanh(equation(t,c,side))-Math.tanh(equation(0,c,side)));
