 for(let i=0;i<=512;i++){const t=TWO*i/512;pts.push(polar(t,c,side));angles.push(bearing(t,c,side));}
 for(let i=1;i<angles.length;i++)if(angles[i]<=angles[i-1])throw Error("Nonmonotone azimuth adapter; swept-plane intersection branch is ambiguous");
 return {pts,angles,side};
}
// Sweep-plane follower: solve intersection of ONE rotating meridional plane
// with EACH complete equation curve. We DO NOT prescribe two curve positions
// and attach a connector to them. The bearing of the bar comes first.
function follow(cur,c,sweep){
 const alpha=((sweep%TWO)+TWO)%TWO;
 const angles=cur.angles;
 let i=0,j=angles.length-1;
 while(j-i>1){const k=(i+j)>>1;if(angles[k]<=alpha)i=k;else j=k;}
