function gcd(a,b){while(b){let c=a%b;a=b;b=c}return a}
function clock(c){const M=Math.round(c.major*20),a=Math.round(c.minor*20),num=M+a,g=gcd(num,a);return{numerator:num/g,denominator:a/g,gear:num/a,shared:a/g}}
