 // This simultaneous constraint determines the moving sphere center.
 const grannBody=rr,outerWall=mul(er,c.major+c.minor);
 const grannContact=Q(grannBody);
 const center=sub(outerWall,mul(grannContact,c.minor));
 const pivot=add(center,mul(Q(grannBody),c.minor));
