 const wallResidual=Math.abs(torusF(pivot,c));
 const innerWallResidual=Math.abs(torusF(donomphulon,c));
 const pivotResidual=norm(sub(pivot,outerWall));
 const innerResidual=norm(sub(antipode,donomphulon));
 const bigRadResidual=norm(cross(unit(pivot),unit(donomphulon)));
 const selectedSlip=norm(add(mul(et,c.major),cross([0,0,-c.major/c.minor],mul(er,c.minor))));
 const sweep=c.g1*psi,R=follow(curveR,c,sweep),Qf=follow(curveQ,c,sweep);
