{"path":"/GitHub/link_6a1a5af1b40c8191affccbb98ac60fa3/create_blob","args":{"repository_full_name":"Satobloc/HsH","content":":root{color-scheme:dark;--bg:#111416;--panel:#181d20;--raised:#20262a;--paper:#e9e4da;--paper-warm:#d8d0c2;--ink:#ece9e1;--muted:#a5aaa7;--line:#343c40;--copper:#b98755;--teal:#6f9f9b;--blue:#7388a4;--violet:#8b8098;--brick:#a8685f;--max:1240px;--serif:Georgia,"Times New Roman",serif;--sans:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;--mono:ui-monospace,SFMono-Regular,Consolas,monospace}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.62 var(--sans)}a{color:#b8d0cd;text-decoration-thickness:1px;text-underline-offset:3px}a:hover{color:#fff}button{font:inherit}
.skip-link{position:absolute;left:-9999px;top:0;background:var(--paper);color:#111;padding:10px;z-index:99}.skip-link:focus{left:10px;top:10px}
.masthead{position:sticky;top:0;z-index:20;display:grid;grid-template-columns:minmax(210px,1fr) auto auto;gap:24px;align-items:center;padding:14px max(24px,calc((100vw - var(--max))/2));background:rgba(17,20,22,.94);border-bottom:1px solid var(--line);backdrop-filter:blur(16px)}
.wordmark{display:flex;flex-direction:column;gap:2px;text-decoration:none;color:var(--ink);min-width:0}.wordmark-kicker{font:10px var(--mono);letter-spacing:.17em;color:var(--copper);text-transform:uppercase}.wordmark-kicker i{font-style:normal;color:var(--muted);padding:0 3px}.wordmark strong{font:600 17px/1.2 var(--serif);white-space:nowrap}
.primary-nav{display:flex;align-items:center;gap:16px;flex-wrap:wrap}.primary-nav a{font-size:12px;color:var(--muted);text-decoration:none;white-space:nowrap}.primary-nav a:hover,.primary-nav a[aria-current=page]{color:var(--paper)}
.header-actions{display:flex;justify-content:flex-end;min-width:70px}.universal-listen-button{border:1px solid #53625e;border-radius:999px;background:#17211f;color:#d4e3dc;padding:6px 12px;font-size:12px;cursor:pointer}.universal-listen-button:hover{background:#263632}
.site-main{width:min(var(--max),calc(100% - 48px));margin:0 auto;min-height:68vh;padding:42px 0 90px}.loading-state{display:flex;align-items:center;gap:12px;color:var(--muted);padding:90px 0}.loading-mark{width:13px;height:13px;border:2px solid var(--teal);border-right-color:transparent;border-radius:50%;display:inline-block}
.eyebrow,.kicker{font:11px var(--mono);letter-spacing:.14em;text-transform:uppercase;color:var(--copper)}h1,h2,h3,h4,p{margin-top:0}h1,h2,h3{font-family:var(--serif);font-weight:500;line-height:1.12;letter-spacing:-.02em}h1{font-size:clamp(42px,6vw,78px);max-width:850px;margin:16px 0 20px}h2{font-size:clamp(29px,3.5vw,46px);margin:0 0 18px}h3{font-size:25px;margin:0 0 10px}h4{font-size:15px;margin:0 0 8px}p{color:#d0d1cb}.lede{font:clamp(18px,2vw,22px)/1.55 var(--serif);color:#d8d7d0;max-width:790px}.small-copy{font-size:13px;color:var(--muted)}.muted{color:var(--muted)}
.page-heading{padding:26px 0 34px;border-bottom:1px solid var(--line);margin-bottom:34px}.page-heading h1{font-size:clamp(38px,5vw,64px);margin:10px 0 14px}.page-heading p{max-width:760px;margin-bottom:0;color:#c7cbc5;font-size:17px}
.hero{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(260px,.85fr);gap:42px;align-items:center;padding:40px 0 58px}.hero-copy{min-width:0}.hero-visual{position:relative;padding:16px;background:#e9e4da;border-radius:4px;box-shadow:0 18px 60px rgba(0,0,0,.25);transform:rotate(.5deg)}.hero-visual img{display:block;width:100%;height:auto;max-height:390px;object-fit:contain}.hero-visual figcaption{color:#3b4140;font:11px/1.45 var(--mono);padding:10px 4px 2px}
.lineage{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:22px 0 24px;color:var(--paper-warm);font:12px var(--mono);letter-spacing:.08em}.lineage b{font-weight:500;color:var(--copper)}
.actions-row{display:flex;gap:10px;flex-wrap:wrap;margin-top:25px}.action-link{display:inline-flex;align-items:center;gap:9px;padding:11px 16px;border:1px solid #52645f;background:#1a2926;color:#e4ede7;text-decoration:none;font-size:13px}.action-link.secondary{background:transparent;border-color:var(--line);color:var(--paper-warm)}.action-link:hover{border-color:var(--teal);background:#23312e}
.section{padding:48px 0;border-top:1px solid var(--line)}.section-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:22px}.section-head p{max-width:600px;margin:0;color:var(--muted);font-size:14px}.section-head a{font-size:12px;white-space:nowrap}
.two-ways{display:grid;grid-template-columns:1fr 1fr;gap:16px}.way-card{padding:28px;border:1px solid var(--line);background:linear-gradient(140deg,#1c2325,#151a1c);min-height:220px}.way-card.idea{border-top:3px solid var(--copper)}.way-card.status{border-top:3px solid var(--teal)}.way-card p{color:#b9c0ba;max-width:530px}.way-card a{font-size:13px}
.card-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.card{background:var(--panel);border:1px solid var(--line);padding:22px;min-width:0}.card .meta{font:10px/1.6 var(--mono);letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin-bottom:10px}.card h3{font-size:23px}.card a{font-size:13px}.card p{font-size:14px;color:#c0c5bf}.card-accent{border-top:3px solid var(--teal)}.card-accent.copper{border-top-color:var(--copper)}.card-accent.blue{border-top-color:var(--blue)}.card-accent.violet{border-top-color:var(--violet)}
