[L2]   "content": "import { attachUniversalListenButton } from './page-listen.js';
const $=(s,r=document)=>r.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const baseURL=new URL(document.querySelector('base').href),basePath=baseURL.pathname,path=location.pathname;
const rel=path.startsWith(basePath)?path.slice(basePath.length):'',page=rel.split('/').filter(Boolean)[0]||'home';
const url=p=>new URL(p,baseURL).href;
const githubFile=p=>'https://github.com/Satobloc/HsH/blob/main/'+String(p).split('/').map(encodeURIComponent).join('/');
const chip=(s,t='teal')=>'<span class="status-chip '+t+'">'+esc(s)+'</span>';
const external=(href,label)=>/^https?:\/\//i.test(String(href||''))?'<a href="'+esc(href)+'" target="_blank" rel="noopener noreferrer">'+esc(label)+'</a>':'';
const load=async n=>{try{const r=await fetch(url('data/'+n),{cache:'no-cache'});if(!r.ok)throw Error(r.status);return await r.json()}catch(_){return null}};
const [work,qf,nf,pf,pi,atlas,registry]=await Promise.all([load('current-work.json'),load('featured-quotes.json'),load('news-feed.json'),load('papers-feed.json'),load('papers.json'),load('atlas.json'),load('instruments.json')]);
const quotes=(qf?.quotes||[]),nathan=quotes.filter(q=>q.speaker_class==='Nathan'),llm=quotes.filter(q=>q.speaker_class==='LLM');
const news=(nf?.items||[]),papers=pi?.papers||[],sources=new Set(papers.map(p=>p.source).filter(Boolean));
const drafts=(pf?.entries||[]).filter(p=>!sources.has(p.manuscript_path)),instruments=registry?.instruments||[];
const daily=a=>a.length?a[Math.floor(Date.now()/86400000)%a.length]:null;
function heading(k,t,d){return '<header class="page-heading"><div class="eyebrow">'+esc(k)+'</div><h1>'+esc(t)+'</h1><p>'+esc(d)+'</p></header>'}
function sourceDetails(p,id){return p?'<details class="source-details"><summary>Source and provenance</summary>'+external(githubFile(p),'Open source record')+(id?'<span class="muted">Message ID: '+esc(id)+'</span>':'')+'</details>':''}
function quoteCard(q,kind){if(!q)return '<div class="empty-state">No featured '+esc(kind)+' quotation is available.</div>';return '<article class="quote-card '+(kind==='LLM'?'llm':'')+'"><div class="meta">Quotable '+esc(kind)+' · '+esc(q.timestamp||'undated')+'</div><blockquote>“'+esc(q.text)+'”</blockquote><div class="quote-by">'+esc(q.speaker_label||kind)+'</div>'+sourceDetails(q.source_path,q.message_id)+'</article>'}
function newsCard(x){return '<article class="news-card"><div class="meta">'+esc(x.external_date||'')+' · '+esc(x.relationship||'External result')+'</div><h3>'+esc(x.headline)+'</h3><p>'+esc(x.external_summary||'')+'</p><div class="why"><div class="eyebrow">Why it caught attention</div><p>'+esc(x.why_it_caught_attention||'')+'</p></div><p class="small-copy">'+external(x.source_url,'Primary source')+' · '+esc(x.source_name||'External source')+'</p>'+(x.sat_hsh_links?.length?'<details class="source-details"><summary>Related project records</summary>'+x.sat_hsh_links.map(z=>'<p>'+external(githubFile(z.path),z.title)+'</p>').join('')+'</details>':'')+'</article>'}
function priorityCard(x){return '<article class="priority"><div class="priority-top"><span class="priority-order">'+esc(x.order||'')+'</span>'+chip(x.status||'In progress','copper')+'</div><h3>'+esc(x.title)+'</h3><p>'+esc(x.audience_summary||'')+'</p></article>'}
function frontCard(x){return '<article class="live-front"><h3>'+esc(x.title)+'</h3><p>'+esc(x.description||'')+'</p></article>'}
function galleryCard(x){return '<figure class="gallery-card"><img src="'+esc(url(x.image))+'" alt="'+esc(x.alt||x.title)+'" loading="lazy" decoding="async"><figcaption><div class="meta">'+esc(x.credit||x.status||'Project visual')+'</div><h3>'+esc(x.title)+'</h3><p>'+esc(x.caption||'')+'</p>'+(x.notes||x.source_path?'<details><summary>Context, status and source</summary><p>'+esc(x.notes||'')+'</p>'+(x.source_path?external(githubFile(x.source_path),'Open SVG source ↗'):'')+'</details>':'')+'</figcaption></figure>'}
function paperCard(x){const pdf=x.site_pdf?'<a class="action-link" href="'+esc(url(x.site_pdf))+'" target="_blank" rel="noopener">Read presented PDF ↗</a>':'';const src=x.source?external(githubFile(x.source),'Source record ↗'):'';return '<article class="paper-card"><div><div class="meta">'+esc((x.date||'')+' · '+(x.status||'')+' · '+(x.authors||[]).join(', '))+'</div><h3>'+esc(x.title)+'</h3><p>'+esc(x.preface||'')+'</p>'+chip('Presented PDF')+(src?'<div class="source-details">'+src+'</div>':'')+'</div><div class="paper-actions">'+pdf+'</div></article>'}
function draftCard(x){const st=String(x.status||'presentation_pending').replace(/_/g,' ');return '<article class="paper-card pending-card"><div><div class="meta">'+esc(x.version||'Manuscript record')+' · '+esc(x.date||'undated')+'</div><h3>'+esc(x.title)+'</h3><p>'+esc(x.summary||'')+'</p><p class="small-copy">'+esc(x.caveat||'No accepted presentation PDF is registered in this build.')+'</p>'+chip('Presentation pending','copper')+'<div class="source-details">'+(x.manuscript_path?external(githubFile(x.manuscript_path),'Manuscript source'): '')+(x.review_path?external(githubFile(x.review_path),'Review record'):'')+(x.acceptance_path?external(githubFile(x.acceptance_path),'Acceptance record'):'')+'</div></div><div class="paper-actions"><span class="status-chip copper">'+esc(st)+'</span></div></article>'}
function labCard(x){const route=String(x.requested_route||'').replace(/^\/+/,''),link=url('../'+route);return '<article class="lab-card"><div class="lab-version">Geometry laboratory · '+esc(x.id)+'</div><h3>'+esc(x.name)+'</h3><p>'+esc(x.kind)+'</p>'+(x.version?'<p class="small-copy">Version '+esc(x.version)+'</p>':'')+'<div class="actions-row"><a class="action-link" href="'+esc(link)+'">Open instrument ↗</a><a class="action-link secondary" href="'+esc(githubFile(x.repo_html))+'" target="_blank" rel="noopener">Source HTML</a></div></article>'}
function home(){
 const n=daily(nathan),l=daily(llm),priorities=(work?.priority_stack||[]).slice(0,3);
 return '<section class="hero"><div class="hero-copy"><div class="eyebrow">An open development record · geometry-first research</div><h1>The Glass Sausage Factory</h1><p class="lede">From <em>Fundamental Intuitions Extended</em> through Scalar–Angular–Torsion and into Hyper(super)Helical Worldtube. The papers are here. So are the conversations, sketches, calculations, false starts, corrections, and current construction.</p><div class="lineage"><b>FIE</b><span>→</span><b>SAT</b><span>→</span><b>H(s)H</b></div><p>The point of the glass is that you do not have to take the finished-looking sentence on trust when the machinery that produced it is available too.</p><div class="actions-row"><a class="action-link" href="visual-atlas/">Start with pictures ↗</a><a class="action-link secondary" href="../">Open the Conversation Viewer ↗</a></div></div>'+(atlas?.length?'<figure class="hero-visual"><img src="'+esc(url(atlas[0].image))+'" alt="'+esc(atlas[0].alt||atlas[0].title)+'"><figcaption>'+esc(atlas[0].title)+' · '+esc(atlas[0].status||'Project visual')+'</figcaption></figure>':'')+'</section>'+
 '<section class="section"><div class="section-head"><div><div class="eyebrow">Choose a reading depth</div><h2>Two ways in</h2></div><p>Same source record. Different jobs. Start with the idea or start with the status and evidence.</p></div><div class="two-ways"><article class="way-card idea"><div class="eyebrow">Idea first</div><h3>Show me the geometry.</h3><p>Start with the pictures and the basic move: treat local observations as readouts of a larger geometric history, then ask what coiling, twisting, recursion, and braiding can organize.</p><a href="visual-atlas/">Enter the Visual Atlas ↗</a></article><article class="way-card status"><div class="eyebrow">Status first</div><h3>Show me what is established.</h3><p>Begin with premise authority, current theory state, translation, formalization, and audit. Historical source, reconstruction, mathematical result, and live hypothesis remain distinct.</p><a href="current-work/">Inspect current work and status ↗</a></article></div></section>'+
 '<section class="section"><div class="section-head"><div><div class="eyebrow">Ancestry</div><h2>A theory with a visible lineage</h2></div><p>The project keeps its developmental sequence visible rather than presenting later terminology as if it had always been there.</p></div><div class="timeline"><article class="timeline-item"><div class="date">c. 1991</div><h3>Recollected precursor</h3><p>An earlier geometric intuition, preserved as recollection.</p></article><article class="timeline-item"><div class="date">2003–04</div><h3>Surviving sketches</h3><p>Early visual and geometric records.</p></article><article class="timeline-item"><div class="date">2024–25</div><h3>FIE and SAT</h3><p>Recovered conversations and the public SAT formulation.</p></article><article class="timeline-item"><div class="date">2026</div><h3>SAT → H(s)H</h3><p>Reconstruction, translation, and finite-core construction.</p></article></div></section>'+
 '<section class="section"><div class="section-head"><div><div class="eyebrow">Research map</div><h2>Where the work is pointed</h2></div><a href="current-work/">Full work map ↗</a></div>'+(work?'<div class="snapshot-note"><strong>Snapshot date: '+esc(work.snapshot_date||'undated')+'</strong><span>'+esc(work.summary||'')+' This is a dated snapshot, not a live status query.</span></div>':'')+'<div class="priority-list">'+priorities.map(priorityCard).join('')+'</div></section>'+
 '<section class="section"><div class="section-head"><div><div class="eyebrow">Interactive instruments</div><h2>Geometry Laboratory</h2></div><a href="laboratory/">Explore both instruments ↗</a></div><div class="lab-grid">'+instruments.map(labCard).join('')+'</div></section>'+
 '<section class="section"><div class="section-head"><div><div class="eyebrow">Selected voices</div><h2>Quotable Nathan / Quotable LLM</h2></div><a href="quotes/">Browse the quotation archive ↗</a></div><div class="quote-grid">'+quoteCard(n,'Nathan')+quoteCard(l,'LLM')+'</div></section>'+
 '<section class="section"><div class="section-head"><div><div class="eyebrow">External science</div><h2>Results, constraints, and curious touchpoints</h2></div><a href="news/">All news cards ↗</a></div><div class="news-grid">'+news.slice(0,2).map(newsCard).join('')+'</div></section>'+
 '<section class="section"><div class="section-head"><div><div class="eyebrow">Reading room</div><h2>Follow the paper trail</h2></div><a href="reading-room/">Open the Reading Room ↗</a></div><p class="lede">Presented documents first. Source records and working manuscripts remain available as secondary provenance, with their status intact.</p><div class="actions-row"><a class="action-link" href="papers/">Browse papers and manuscripts ↗</a><a class="action-link secondary" href="../">Inspect the conversations ↗</a></div></section>';
}
function currentPage(){return heading('Research map','Current work','A source-linked snapshot of active priorities and construction fronts. The date belongs to the feed, not to the current browser session.')+(work?'<div class="snapshot-note"><strong>Snapshot: '+esc(work.snapshot_date||'undated')+'</strong><span>'+esc(work.summary||'')+'</span></div><section class="section"><div class="eyebrow">Priority stack</div><h2>What is being pushed forward</h2><div class="priority-list">'+(work.priority_stack||[]).map(priorityCard).join('')+'</div></section><section class="section"><div class="eyebrow">Live fronts</div><h2>Active construction and reconstruction</h2><div class="live-fronts">'+(work.live_fronts||[]).map(frontCard).join('')+'</div></section><section class="section"><div class="eyebrow">Controlling sources</div><h2>Read the authority surfaces</h2><div class="card-grid">'+(work.controlling_sources||[]).map(s=>'<article class="card"><div class="meta">'+esc(s.role)+'</div><h3>'+esc(s.path)+'</h3><a href="'+esc(githubFile(s.path))+'" target="_blank" rel="noopener">Open source ↗</a></article>').join('')+'</div></section>':'<div class="empty-state">The Current Work snapshot is unavailable.</div>')}
function atlasPage(){return heading('Visual Atlas','The pictures are part argument, part memory, part provenance.','A thumbnail-first route into selected project diagrams. Each item keeps its title, caption, and source context attached.')+(atlas?.length?'<div class="gallery-grid">'+atlas.map(galleryCard).join('')+'</div>':'<div class="empty-state">No locally mirrored, approved gallery assets are available. Staged and unreviewed images are intentionally excluded.</div>')+'<div class="callout"><p>Additional historical and podcast imagery is being mirrored from original source locations. The gallery admits only locally available assets with approved status and repository-backed provenance.</p></div>'}
function newsPage(){return heading('External science','Results, constraints, and curious touchpoints','External research is placed beside specific SAT/H(s)H explorations with a typed relationship. A comparison target is not a claim of support.')+(news.length?'<div class="news-grid">'+news.map(newsCard).join('')+'</div>':'<div class="empty-state">No featured news cards are registered.</div>')}
function quotesPage(){return heading('Quotation archive','Quotable Nathan / Quotable LLM','Exact Nathan-authored excerpts and project-generated LLM prose are presented as separate streams. Each quotation retains its source pointer.')+'<section class="section"><div class="eyebrow">Nathan</div><h2>Quotable Nathan</h2><div class="quote-grid">'+nathan.map(q=>quoteCard(q,'Nathan')).join('')+'</div></section><section class="section"><div class="eyebrow">Project-generated prose</div><h2>Quotable LLM</h2><div class="quote-grid">'+llm.map(q=>quoteCard(q,'LLM')).join('')+'</div></section>'}
function papersPage(){return heading('Papers and manuscripts','Research documents, with their status attached','A public presentation PDF is a distinct object from its source manuscript, review record, or editorial feed entry.')+'<section class="section"><div class="eyebrow">Presented documents</div><h2>Published reading copies</h2>'+(papers.length?'<div class="paper-list">'+papers.map(paperCard).join('')+'</div>':'<div class="empty-state">No complete, registered presentation PDFs are available.</div>')+'</section><section... (truncated)

