   175	 let prev=analemmaSpeed(0);
   176	 for(let i=1;i<=n;i++){const t=i*dt,next=analemmaSpeed(t);
   177	  angles.push(t);arc.push(arc[i-1]+dt*(prev+4*analemmaSpeed(t-dt/2)+next)/6);prev=next}
   178	 const L=arc[n];
   179	 if(Math.abs(L-ANALEMMA_UNIT_LENGTH)>2e-10)
   180	  throw Error('Numerical Analemma length disagrees with the locked gear constant');
   181	 function at(psi){
   182	  let s=(delta*psi)%L;if(s<0)s+=L;if(s<1e-10||s>L-1e-10)s=0;
   183	  let i=0,j=n;while(j-i>1){const k=(i+j)>>1;if(arc[k]<=s)i=k;else j=k}
   184	  const t0=angles[i],t1=angles[j],v0=analemmaSpeed(t0);
   185	  let t=t0+(t1-t0)*(s-arc[i])/(arc[j]-arc[i]);
   186	  for(let k=0;k<4;k++){
   187	   const d=t-t0,integral=d*(v0+4*analemmaSpeed((t0+t)/2)+analemmaSpeed(t))/6;
   188	   t=Math.max(t0,Math.min(t1,t-(arc[i]+integral-s)/Math.max(1e-12,analemmaSpeed(t))));
   189	  }
   190	  return analemmaFrame(t);
   191	 }
   192	 return{at,track:t=>analemma(t),scale:ANALEMMA_K,L,cycles,delta};
   193	}
   194	let cam=null;
   195	function clock(c){const v=cam||buildCam(c),sweeps=Math.max(1,Math.round(c.g1));
   196	 return{roll:c.major/c.minor,turns:v.cycles,sweeps,elbowTurns:lcm(v.cycles,sweeps),shared:1,analemmaLength:v.L*c.minor}}
   197	function sample(psi,c){
   198	 const k=clock(c),er=[Math.cos(psi),Math.sin(psi),0],et=[-Math.sin(psi),Math.cos(psi),0],ez=[0,0,1],b=cam.at(psi);
   199	 // Lock the analemma material normal, tangent, and cross normal to
   200	 // inner-wall contact -er, torus forward tangent +et and -ez.
   201	 const Q=v=>add(add(mul(er,-dot(b.g,v)),mul(et,dot(b.t,v))),mul(ez,-dot(b.h,v)));
   202	 const inWall=mul(er,c.major-c.minor),outWall=mul(er,c.major+c.minor);
   203	 const center=sub(inWall,mul(Q(b.g),c.minor)),contact=add(center,mul(Q(b.g),c.minor)),
   204	 antipode=add(center,mul(Q(mul(b.g,-1)),c.minor));
   205	 const omega=add(mul(er,b.kg*cam.delta),mul(ez,k.roll));
   206	 const selectedSlip=norm(add(mul(et,c.major),cross(omega,mul(er,-c.minor))));
   207	 const sweep=k.sweeps*psi,A=follow(curveR,c,sweep),B=follow(curveQ,c,sweep),
   208	 pr=add(center,mul(Q(A.p),c.minor)),pq=add(center,mul(Q(B.p),c.minor)),
   209	 dir=unit(sub(pq,pr)),mid=mul(add(pr,pq),.5);
   210	 let ref=Q([0,0,1]);if(Math.abs(dot(ref,dir))>.9)ref=Q([0,1,0]);
   211	 const u=unit(sub(ref,mul(dir,dot(ref,dir)))),v=unit(cross(dir,u)),
   212	 theta=k.elbowTurns*psi,elbow=unit(add(mul(u,Math.cos(theta)),mul(v,Math.sin(theta))));
   213	 return{center,pr,pq,mid,dir,elbow,contact,pivot:outWall,donomphulon:inWall,antipode,
   214	  bigRadStart:[0,0,0],bigRadEnd:outWall,grannBody:b.g,grannSpin:cam.delta*psi,
   215	  grannGear:k.turns,grannTurns:k.turns,elbowTurns:k.elbowTurns,radialSpin:b.kg*cam.delta,
   216	  selectedContact:'INNER',angularVelocity:omega,bodyForwardOmegaZ:k.roll,
   217	  wallResidual:Math.abs(torusF(contact,c)),innerWallResidual:Math.abs(torusF(outWall,c)),
   218	  pivotResidual:norm(sub(antipode,outWall)),innerResidual:norm(sub(contact,inWall)),
   219	  bigRadResidual:norm(cross(unit(inWall),unit(outWall))),selectedSlip,Q,er,r:A.p,q:B.p,
   220	  grannCircle:t=>add(center,mul(Q(cam.track(t)),c.minor)),grannBodyCircle:t=>cam.track(t),
   221	  curvatureR:A.turn,curvatureQ:B.turn,curvatureSignal:b.kg,tR:A.t,tQ:B.t,sweep,
   222	  planeR:A.planeResidual,planeQ:B.planeResidual,midOffset:norm(sub(mid,center))/c.minor,
   223	  elbowDot:dot(elbow,dir),analemmaPhase:cam.delta*psi,analemmaCurvature:b.kg};
   224	}
   225	function torusF(v,c){let r=Math.hypot(v[0],v[1]);return (r-c.major)**2+v[2]**2-c.minor**2}
   226	function rayHit(origin,ray,c){ // Find earliest positive crossing via bracketed 1D solves; equation is torus implicit, equivalent to quartic zeros.
   227	 let r0=torusF(origin,c),bound=2*(c.major+c.minor)+3;let lastx=0,lastf=r0,steps=100;for(let j=1;j<=steps;j++){let x=bound*j/steps,f=torusF(add(origin,mul(ray,x)),c);if((lastf<0&&f>=0)||(lastf>0&&f<=0)){let lo=lastx,hi=x,flo=lastf;for(let k=0;k<35;k++){let mid=(lo+hi)/2,fm=torusF(add(origin,mul(ray,mid)),c);if((fm>0)===(flo>0)){lo=mid;flo=fm}else hi=mid}return add(origin,mul(ray,(lo+hi)/2))}lastx=x;lastf=f}return null}
   228	function rebuild(){
   229	 if(data.length){previousTrace=data.map(s=>s.hit);previousLabel=currentLabel}
   230	 currentLabel=chosen('r').title+' / '+chosen('q').title;
   231	 cfg=params();cam=buildCam(cfg);updateCatalog();const k=clock(cfg);sharedTurns=1;N=1401;
   232	 curveR=curve(cfg,'r');curveQ=curve(cfg,'q');data=[];
   233	 for(let i=0;i<N;i++){const s=sample(TWO*i/(N-1),cfg);s.hit=rayHit(s.mid,s.elbow,cfg);data.push(s)}
   234	 if(previousTrace&&previousTrace.length===N){
   235	  const ds=data.map((s,i)=>s.hit&&previousTrace[i]?norm(sub(s.hit,previousTrace[i])):null).filter(x=>x!==null);
   236	  const rms=Math.sqrt(ds.reduce((a,x)=>a+x*x,0)/Math.max(1,ds.length)),peak=Math.max(0,...ds);
   237	  $('#differenceStatus').textContent='Previous: '+previousLabel+' | Current: '+currentLabel+
   238	  ' | torus-wall RMS Δ '+rms.toFixed(5)+' ('+(100*rms/cfg.minor).toFixed(2)+'% tube radius)'+
   239	  ' · peak Δ '+peak.toFixed(5)+
   240	  (rms<1e-8?' · identical mapped outputs; different equation labels may share the same sampled function.':' · geometrically distinct output; no aesthetic ranking.');
   241	 }else $('#differenceStatus').textContent='Change R or Q to compare the previous physically computed torus-wall trace.';
   242	 const neighborSteps=data.slice(1).map((s,i)=>s.hit&&data[i].hit?norm(sub(s.hit,data[i].hit)):null);
   243	 const jumpLimit=.2*cfg.minor,largeJumps=neighborSteps.filter(d=>d!==null&&d>jumpLimit).length,
   244	 largestJump=Math.max(0,...neighborSteps.filter(d=>d!==null));
   245	 const max=v=>Math.max(...data.map(s=>Math.abs(s[v]))),hits=data.filter(s=>s.hit).length;
   246	 const NS=data.filter(s=>s.r[2]<=0||s.q[2]>=0).length,
   247	 plane=Math.max(...data.map(s=>Math.max(s.planeR,s.planeQ))),
   248	 seam=data[0].hit&&data.at(-1).hit?norm(sub(data[0].hit,data.at(-1).hit)):NaN;
   249	 const a=sample(0,cfg),b=sample(TWO,cfg),frame=Math.max(...[[1,0,0],[0,1,0],[0,0,1]].map(v=>norm(sub(a.Q(v),b.Q(v)))));
   250	 $('#stats').textContent='INNER torus wall · physical rolling spin +'+k.roll.toFixed(3)+
   251	 ' (same direction as orbit) · min shared return 1 torus circuit'+
   252	 ' · Analemma '+k.turns+' material circuits · R/Q sweep '+k.sweeps+
   253	 ' · LCM elbow '+k.elbowTurns+' rotations · radial spin '+Math.max(...data.map(s=>Math.abs(s.radialSpin))).toFixed(3)+
   254	 ' · frame seam '+frame.toExponential(1)+' · trace seam '+seam.toExponential(1)+
   255	 ' · N/S violations '+NS+' · meridian error '+plane.toExponential(1)+
   256	 ' · perpendicular error '+max('elbowDot').toExponential(1)+' · wall hits '+hits+'/'+N+
   257	 ' · W_obble max offset '+max('midOffset').toFixed(3)+' b · adjacent jumps above '+jumpLimit.toFixed(3)+': '+largeJumps+
   258	 ' (max '+largestJump.toFixed(3)+'; may involve wall-hit branch changes; not smoothed)';
