# Inspect exact quartic root sets around the largest output jumps.
from pathlib import Path
from playwright.sync_api import sync_playwright
import numpy as np, math, json
html=Path('/tmp/whirligig-pages/site/laboratory/whirligig/index.html').read_text().replace('applyPair();requestAnimationFrame(loop)})();</script>','applyPair();window.__debug={data,cfg};requestAnimationFrame(loop)})();</script>')
with sync_playwright() as pw:
 b=pw.chromium.launch(headless=True,executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page();p.set_content(html,wait_until='load');raw=p.evaluate('''()=>({R:window.__debug.cfg.major,b:window.__debug.cfg.minor,data:window.__debug.data.map(s=>({o:s.mid,d:s.elbow,hit:s.hit}))})''');b.close()
R,b=raw['R'],raw['b']
def roots_for(s):
 o=np.array(s['o']);d=np.array(s['d']);X0=o[0]**2+o[1]**2;X1=2*(o[0]*d[0]+o[1]*d[1]);X2=d[0]**2+d[1]**2;A0=X0+o[2]**2+R**2-b**2;A1=X1+2*o[2]*d[2];A2=1.;co=[A2*A2,2*A1*A2,A1*A1+2*A0*A2-4*R**2*X2,2*A0*A1-4*R**2*X1,A0*A0-4*R**2*X0]; rr=[]
 for z in np.roots(co):
  if abs(z.imag)<1e-5 and z.real>0:
   lam=float(z.real);x=o+lam*d;rho=np.hypot(x[0],x[1]);A=A0+A1*lam+A2*lam*lam;res=abs((rho-R)**2+x[2]**2-b*b)
   if A>=-1e-5 and res<1e-5:rr.append(lam)
 return sorted(rr)
for center in [72,183]:
 print('CENTER',center)
 for i in range(center-3,center+4):
  r=roots_for(raw['data'][i]); h=np.array(raw['data'][i]['hit']);o=np.array(raw['data'][i]['o']);d=np.array(raw['data'][i]['d']);lam=float(np.dot(h-o,d))
  print(i,'roots',[round(x,8) for x in r],'selected',round(lam,8))
